"""Extend the frozen eight-recipe survey without rewriting discovery/SAM catalogs."""
from pathlib import Path
import json,hashlib
root=Path(__file__).resolve().parent.parent;out=root/'output/library-shape-survey-v2';out.mkdir(exist_ok=True)
manifest=json.loads((root/'output/library-shape-survey-v1/manifest.json').read_text())
recipes=json.loads((out/'baseline-eight-recipes.json').read_text())
def p(id,label,v,lo,hi,step=.001):return dict(id=id,label=label,value=v,min=lo,max=hi,step=step)
specs=[
('faceted-spire','Folded chevron spire','Folded volumes',[609],[p('folds','Nested folds',5,2,10,1),p('spread','Wing span',.88,.4,1),p('notch','Inner notch height',.42,.18,.7),p('spine','Fold axis',.5,.32,.68),p('facets','Facet contrast',.55,0,1)],'Build nested concave chevrons around one vertical spine. Each wing shares its apex and inner notch with its partner; opacity contrast distinguishes the two folded planes.','folded-chevron axial-fold concave-polygon faceted-volume',[1,.05,.5,.7,.9,.7,.95,.7]),
('sliced-orb','Displaced sliced orb','Shaded volumes',[830],[p('slices','Slice count',6,2,12,1),p('meridians','Wireframe meridians',7,3,15,1),p('displacement','Slice displacement',.09,0,.24),p('phase','Displacement phase',.6,-1.2,1.2),p('gap','Slice gap',.012,.003,.045),p('light','Light position',-.45,-.8,.8)],'Clip a shaded ellipsoid and its wireframe into horizontal bands. Translate each band independently with a seeded-phase sinusoid; retain a common ellipsoid coordinate system, so the displaced bands remain sections of one volume. Gradient shading and wireframe paths remain vector PDF content.','slice-displacement clipped-volume wireframe tonal-shading',[.3,.9,.8,.65,.7,.3,.85,1]),
('gravity-drips','Gravity-fed pigment trails','Material flows',[1094],[p('count','Pigment streams',13,4,28,1),p('pool','Pool radius',.115,.045,.18),p('length','Gravity reach',.67,.24,.77),p('width','Stream width',.014,.004,.034),p('wind','Lateral drift',.06,-.2,.2),p('taper','Tail thickness',.55,.15,.85)],'Sample a coherent band of pigment pools. Grow each connected tapered trail downward from inside its own pool; a private seeded stream determines pool sizes and trail lengths. Wind bends the trails while gravity keeps their vertical extent positive. This is a vector flow grammar, not a fluid simulation.','gravity-trails pigment-pools connected-flow seeded-material',[.05,.95,.65,.65,.3,.4,1,.15]),
('bilateral-soft-cross','Soft four-lobed cross','Organic silhouettes',[1010],[p('neck','Central neck',.2,.11,.3),p('bulge','Lobe fullness',.7,.22,1),p('stretch','Vertical stretch',1.03,.65,1.4),p('stem','Stem reach',.12,0,.3),p('glow','Surface glow',.65,0,1)],'Modulate a polar radius with fourfold symmetry to form four broad lobes and concave waists. Normalize the silhouette before stretching, optionally extend a central stem, and apply a separately controlled radial surface glow.','four-lobed bilateral-symmetry concave-waist soft-cross gradient-material',[.05,1,.25,.85,1,.65,.4,.4]),
('portal-type','Projective type portal','Spatial typography',[639,1030],[p('levels','Depth levels',3,1,6,1),p('faces','Text planes',4,2,4,1),p('depth','Perspective recession',.44,.2,.7),p('focusX','Vanishing point X',.53,.25,.75),p('focusY','Vanishing point Y',.5,.25,.75),p('guides','Frame visibility',.35,0,1)],'Shape editable brief words with Core Text. Flatten glyph curves, then project every outline through a homography onto receding quadrilateral walls. Keep text, font metadata and depth controls in the element genome; optional frame guides expose the shared vanishing point.','projective-type homography glyph-outlines vanishing-point editable-text',[.85,.1,.85,.45,.95,.8,1,.9]),
('module-substitution','Glyph and image density field','Modular typography',[745,1122],[p('rows','Module rows',12,4,24,1),p('columns','Module columns',9,3,18,1),p('bias','Density exponent',1.65,.55,3.2),p('mass','Module ink area',.56,.25,.82),p('moduleKind','Glyphs / symbols',0,0,1,1),p('rotation','Module rotation',0,-.8,.8)],'Distribute editable brief glyphs on a nonuniform grid. Normalize glyph scale by measured outline ink area, with a cell-size cap for narrow forms. Switch to geometric symbols, or attach a checksum-verified rasterAsset to reuse the same layout with cropped image modules. Glyph and symbol exports remain vector; image modules embed their raster source.','module-substitution ink-area-normalization glyph-density image-modules editable-text',[.3,.5,.9,.35,.9,.45,.85,0])]
traits=['angularity','curvature','detail','mass','regularity','counterform','directionality','volume'];systems=json.loads((root/'output/library-shape-survey-v1/systems.json').read_text())['recipes']
for id,name,group,indices,params,logic,tags,vector in specs:
 refs=[dict(queryID='visual-census-2026-11-08',posterID=manifest[i]['id'],sourceImageSHA256=manifest[i]['sha256'],evidenceURL=(root/'output/library-shape-survey-v1/manifest.json').as_uri()) for i in indices]
 recipe=dict(id='survey-'+id,name=name,group=group,renderer='motif-survey-'+id,parameters=params,traits=dict(zip(traits,vector)),styles=['abstract','optical','experimental','color-field'],fontTarget=dict(weight=.7 if id in ['faceted-spire','bilateral-soft-cross','portal-type'] else .45,width=1,serif=.55 if id=='sliced-orb' else 0,mono=.8 if id=='module-substitution' else 0,italic=0),idealAspect=.7 if id in ['faceted-spire','gravity-drips'] else 1,tags=tags.split(),logic=logic,references=refs,basis='Source-reviewed parametric interpretation; exact original construction and authorship unknown. No traced source outlines or trained aesthetic labels.')
 
 if id=='sliced-orb':recipe['basis']='The FUBU reference supports shaded wireframe volumes. It does not literally contain separated displaced slices; slicing and lateral displacement are an authored procedural extension.'
 recipes.append(recipe);systems.append(dict(recipeID=recipe['id'],sourceIndices=indices,observation=logic,shapeType=id,controls=[p['id'] for p in params],implementation=dict(geometry='native-vector' if id!='module-substitution' else 'vector-glyphs-and-optional-raster-modules',typeInteractions='projective editable text' if id=='portal-type' else 'actual brief glyph substitution' if id=='module-substitution' else 'existing composition placement'),composition=dict(preferredScale=[.55,1.25],copies=[1,2],optional=True,cropModes=['span','zoom','offset','edge','corner'])))
assert len(recipes)==14 and len({r['id'] for r in recipes})==14
(root/'Sources/PosterCore/Resources/ShapeLibrary/SurveyRecipes.json').write_text(json.dumps(recipes,indent=2,ensure_ascii=False)+'\n')
(out/'systems.json').write_text(json.dumps(dict(version='library-survey-systems-v2',recipes=systems,futureSystems=[],sourceManifestSHA256=hashlib.sha256((root/'output/library-shape-survey-v1/manifest.json').read_bytes()).hexdigest()),indent=2,ensure_ascii=False)+'\n')
print('14 recipes; all six former proposals implemented')
